    df = pd.read_json(io.StringIO(raw_json))
    
    # Adicionar flag ética de Acompanhamento / Atendimento Adaptado
    df['tipo_avaliacao'] = df['aluno'].apply(lambda x: 'Adaptada' if x in ALUNOS_ATENDIMENTO_ADAPTADO else 'Convencional')
    df['is_adaptado'] = df['aluno'].isin(ALUNOS_ATENDIMENTO_ADAPTADO)
    
    # Indicadores auxiliares de desempenho
    df['em_rp_1'] = df['media_1'] < 7.0
    df['em_rp_2'] = df['media_2'] < 7.0
    df['recuperado_1'] = (df['media_1'] < 7.0) & (df['final_1'] >= 7.0)
    df['recuperado_2'] = (df['media_2'] < 7.0) & (df['final_2'] >= 7.0)
    df['permaneceu_1'] = (df['media_1'] < 7.0) & (df['final_1'] < 7.0)
    df['permaneceu_2'] = (df['media_2'] < 7.0) & (df['final_2'] < 7.0)
    df['abaixo5_1'] = df['final_1'] < 5.0
    df['abaixo5_2'] = df['final_2'] < 5.0
    
    # Indicadores comparativos 1ª x 2ª Etapa
    df['evolucao_nota'] = df['final_2'] - df['final_1']
    df['evolucao_media_orig'] = df['media_2'] - df['media_1']
    return df

